diff --git a/source/standalone/wave6-hook-inventory.ts b/source/standalone/wave6-hook-inventory.ts
new file mode 100644
index 0000000..88c4cbf
--- /dev/null
+++ b/source/standalone/wave6-hook-inventory.ts
@@ -0,0 +1,36 @@
+export type InitHookInventoryOptions = {
+	readonly hooks?: {
+		readonly init?: unknown;
+	};
+};
+
+const anonymousHookName = '<anonymous>';
+
+/**
+Lists the names of the `init` hooks of an options object, in source order.
+
+Unlike the `init` step of `Options`, no hook is invoked and neither options object is mutated. The second argument mirrors the `withOptions` argument of that step and is never read.
+
+@returns The hook names, using `<anonymous>` for hooks without a name, or an empty array when `hooks.init` is absent.
+@throws {TypeError} When `hooks.init` is present but not an array, or when any of its elements is not a function.
+*/
+// eslint-disable-next-line @typescript-eslint/naming-convention
+export const vendored_hook_inventory_variant = (options: InitHookInventoryOptions, _withOptions?: InitHookInventoryOptions): string[] => {
+	const initHooks = options.hooks?.init;
+
+	if (initHooks === undefined) {
+		return [];
+	}
+
+	if (!Array.isArray(initHooks)) {
+		throw new TypeError(`Expected \`hooks.init\` to be an array, got ${initHooks === null ? 'null' : typeof initHooks}`);
+	}
+
+	return initHooks.map((hook: unknown, index) => {
+		if (typeof hook !== 'function') {
+			throw new TypeError(`Expected \`hooks.init[${index}]\` to be a function, got ${hook === null ? 'null' : typeof hook}`);
+		}
+
+		return hook.name === '' ? anonymousHookName : hook.name;
+	});
+};
diff --git a/test/wave6-hook-inventory.ts b/test/wave6-hook-inventory.ts
new file mode 100644
index 0000000..2b4ea00
--- /dev/null
+++ b/test/wave6-hook-inventory.ts
@@ -0,0 +1,81 @@
+import test from 'ava';
+import {vendored_hook_inventory_variant as inventory} from '../source/standalone/wave6-hook-inventory.js';
+
+test('returns init hook names in source order', t => {
+	function first() {}
+	function second() {}
+
+	t.deepEqual(inventory({hooks: {init: [first, second]}}), ['first', 'second']);
+});
+
+test('uses `<anonymous>` for hooks without a name', t => {
+	const named = () => {};
+	const hooks = [(() => () => {})(), named];
+
+	t.deepEqual(inventory({hooks: {init: hooks}}), ['<anonymous>', 'named']);
+});
+
+test('returns an empty array when `hooks.init` is absent', t => {
+	t.deepEqual(inventory({}), []);
+	t.deepEqual(inventory({hooks: {}}), []);
+});
+
+test('returns an empty array for an empty `hooks.init`', t => {
+	t.deepEqual(inventory({hooks: {init: []}}), []);
+});
+
+test('throws on a non-array `hooks.init`', t => {
+	t.throws(() => inventory({hooks: {init() {}}}), {instanceOf: TypeError});
+	t.throws(() => inventory({hooks: {init: null}}), {instanceOf: TypeError});
+	t.throws(() => inventory({hooks: {init: 'init'}}), {instanceOf: TypeError});
+});
+
+test('throws on a non-callable element', t => {
+	t.throws(() => inventory({hooks: {init: [() => {}, 'hook']}}), {
+		instanceOf: TypeError,
+		message: /hooks\.init\[1]/,
+	});
+	t.throws(() => inventory({hooks: {init: [undefined]}}), {instanceOf: TypeError});
+});
+
+test('does not invoke any hook, unlike the `init` step of `Options`', t => {
+	let calls = 0;
+	const hook = () => {
+		calls++;
+	};
+
+	const result = inventory({hooks: {init: [hook, hook]}}, {});
+
+	t.is(calls, 0);
+	t.deepEqual(result, ['hook', 'hook']);
+});
+
+test('returns names instead of undefined', t => {
+	const a = () => {};
+
+	t.not(inventory({hooks: {init: [a]}}), undefined);
+});
+
+test('does not mutate either options object', t => {
+	const hook = (raw: Record<string, unknown>) => {
+		raw.mutated = true;
+	};
+
+	const init = [hook];
+	const options = Object.freeze({hooks: Object.freeze({init: Object.freeze(init)})});
+	const withOptions: {hooks?: {init?: unknown}; mutated?: boolean} = {};
+
+	t.deepEqual(inventory(options, withOptions), ['hook']);
+	t.deepEqual(withOptions, {});
+	t.deepEqual(options.hooks.init, [hook]);
+});
+
+test('accepts a structural options object', t => {
+	const structural = () => {};
+
+	class Custom {
+		hooks = {init: [structural]};
+	}
+
+	t.deepEqual(inventory(new Custom()), ['structural']);
+});
